set nocount on

SELECT 
    a.ma_kh, a.ten_kh, a.ten_kh2, a.dia_chi, a.home_page, a.ma_ttp, a.rg_code, 
    a.nguoi_lh, a.ma_cv, a.e_mail, a.dien_thoai, a.nh_kh1, a.nh_kh2, a.nh_kh3, a.ghi_chu,
    b.ten_nh AS ten_nh_kh1, c.ten_nh AS ten_nh_kh2, d.ten_nh AS ten_nh_kh3,
    e.ten_ttp, f.rgname, g.ten_cv into #dmkh0full
FROM 
    dmkh0 a
LEFT JOIN dmnh b ON a.nh_kh1 = b.ma_nh AND b.ma_loai_nh = 'KH1'
LEFT JOIN dmnh c ON a.nh_kh2 = c.ma_nh AND c.ma_loai_nh = 'KH2'
LEFT JOIN dmnh d ON a.nh_kh3 = d.ma_nh AND d.ma_loai_nh = 'KH3'
LEFT JOIN dmttp e ON a.ma_ttp = e.ma_ttp
LEFT JOIN sysregioninfo f ON a.rg_code = f.rg_code
LEFT JOIN dmchucvu g ON a.ma_cv = g.ma_cv

select @@fields into #t from thpkhct a @@join
where @@key order by line
select * from #t order by line
drop table #t, #dmkh0full









