function dir$thpkh(p){
  this.constructor(p);
    document._dir = p;
}
dir$thpkh.prototype = new DirEvent();
dir$thpkh.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
}

dir$thpkh.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid()
  var exp = {

    t_chon_yn: ['@t_chon_yn', '[chon_yn]'],

  }
  p.applyExpression(exp, g, false);

  g.FomulaApplied = {
    "chon_yn":["t_chon_yn"],
	"ma_kh":["chon_yn","t_chon_yn"]
  }


  dir$thpkhDisabledMasterField(p, g);
  dir$thpkhDisabledStatusByAction(p);
}

dir$thpkh.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir, g = p.grid(0), dt = g.data;
  switch (id) {
    case 'ok':
		var d = p.valForm('ngay_hl'),d2 = p.valForm('ngay_hld');
		var k = $.date(d,"dd/mm/yy"),k2 = $.date(d2,"dd/mm/yy");
		if (p.valForm('ngay_hld') <= p.valForm('ngay_hl')) { 
			$.alert(p.msg('noDate')+' ' + k + ' < ' + k2);			
			return false;
		}
    default:
      break;
  }
  return true;
}
dir$thpkh.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
  	case '10':
      p.showFilter("thpkhKH0", null, {_ngay_thuchien2: p.valForm('ngay_ct'),_unit_id: p.valForm('unit_id')});	  
	  return false;
      break;
    default:
      break;
  }
  return true;
}

dir$thpkh.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir;
  switch (c){
      case 'ma_kh':
		p.grequest(g, 'loadName', '', ['ma_kh'], null, r);
      break;
    default:
      break;
  }
}
dir$thpkh.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){

    default:
      break;
  }
}

dir$thpkh.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$thpkhDisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$thpkhDisabledMasterField(p, g){

}

function dir$thpkhDisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=4],[value=0],[value=5],[value=6],[value=7],[value=9]").remove();
}








