			SELECT a.ten_kh as #ten_kh, a.dia_chi as #dia_chi, a.home_page as #home_page, a.ma_ttp, CAST('' as nvarchar(256)) as #ten_ttp, a.rg_code, CAST('' as nvarchar(256)) as #rgname, a.ma_cv, CAST('' as nvarchar(256)) as #ten_cv, a.e_mail as #e_mail, a.dien_thoai as #dien_thoai, a.nh_kh1, CAST('' as nvarchar(256)) as #ten_nh_kh1, a.nh_kh2, CAST('' as nvarchar(256)) as #ten_nh_kh2, a.nh_kh3, CAST('' as nvarchar(256)) as #ten_nh_kh3
			INTO #data
			FROM dmkh0 a WITH (NOLOCK)
			WHERE ma_kh = @ma_kh

			update #data set #ten_ttp = (select isnull(max(ten_ttp), '') from dmttp where ma_ttp = #data.ma_ttp)
			update #data set #rgname = (select isnull(max(rgname), '') from sysregioninfo where rg_code = #data.rg_code)
			update #data set #ten_cv = (select isnull(max(ten_cv), '') from dmchucvu where ma_cv = #data.ma_cv)
			update #data set #ten_nh_kh1 = (select isnull(max(ten_nh), '') from dmnh where ma_nh = #data.nh_kh1 and ma_loai_nh ='KH1')
			update #data set #ten_nh_kh2 = (select isnull(max(ten_nh), '') from dmnh where ma_nh = #data.nh_kh2 and ma_loai_nh ='KH2')
			update #data set #ten_nh_kh3 = (select isnull(max(ten_nh), '') from dmnh where ma_nh = #data.nh_kh3 and ma_loai_nh ='KH3')

			SELECT * FROM #data

			DROP TABLE #data









